import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except (json.JSONDecodeError, TypeError):
        raise ValueError("Malformed JSON data")

    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("JSON data is empty or not a list")

    processed_data = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Invalid item in JSON data")
        if 'Country' not in item or 'Population' not in item:
            raise ValueError("Missing Country or Population key")

        country = item['Country']
        population = item['Population']

        if not isinstance(country, str):
            raise ValueError("Country name must be a string")

        if not isinstance(population, (int, float)) or population < 0:
            raise ValueError("Population must be a non-negative number")

        processed_data.append({
            "Country": country,
            "Population": math.floor(population)
        })

    df = pd.DataFrame(processed_data)

    file_path = os.path.join(output_dir, file_name)

    try:
        os.makedirs(output_dir, exist_ok=True)
        df.to_csv(file_path, index=False)
    except Exception:
        raise IOError("Cannot write to specified directory")

    return os.path.abspath(file_path), df

import re
import json
# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    try:
        data = json.loads(ip_address)
        text = str(data)
    except json.JSONDecodeError:
        return 'Invalid IP address received'

    match = re.search(IP_REGEX, text)
    if not match:
        return 'Invalid IP address received'

    ip = match.group(0)
    parts = ip.split('.')

    for part in parts:
        if not (0 <= int(part) <= 255):
            return 'Invalid IP address received'

    return ip
